class beam_effect;

void *operator new(unsigned int);
void operator delete(void *);

template<class T>
struct my_allocator {
  static T *allocate(unsigned int n) { return (T *)operator new(n * sizeof(T)); }
  static void deallocate(T *p) { operator delete(p); }
};

template<class T, class Alloc>
class vector {
public:
  typedef T *iterator;
  typedef unsigned int size_type;

  T *_M_start;
  T *_M_finish;
  T *_M_end_of_storage;

  size_type size() const { return _M_finish - _M_start; }
  T *_M_allocate(size_type n) { return Alloc::allocate(n); }
  void _M_deallocate(T *p, size_type) { Alloc::deallocate(p); }
  void _M_insert_aux(iterator, const T &);
};

template<class T>
inline void construct(T *p, const T &value)
{
  *p = value;
}

template<class T>
inline void destroy(T *, T *)
{
}

template<class T>
inline T *copy_backward(T *first, T *last, T *result)
{
  while (first != last)
    *--result = *--last;
  return result;
}

template<class T>
inline T *uninitialized_copy(T *first, T *last, T *result)
{
  while (first != last)
    *result++ = *first++;
  return result;
}

template<class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T &x)
{
  if (_M_finish != _M_end_of_storage) {
    construct(_M_finish, *(_M_finish - 1));
    ++_M_finish;
    copy_backward(position, _M_finish - 2, _M_finish - 1);
    *position = x;
  } else {
    const size_type old_size = size();
    const size_type len = old_size != 0 ? 2 * old_size : 1;
    iterator new_start = _M_allocate(len);
    iterator new_finish = new_start;
    new_finish = uninitialized_copy(_M_start, position, new_start);
    construct(new_finish, x);
    ++new_finish;
    new_finish = uninitialized_copy(position, _M_finish, new_finish);
    destroy(_M_start, _M_finish);
    _M_deallocate(_M_start, _M_end_of_storage - _M_start);
    _M_start = new_start;
    _M_finish = new_finish;
    _M_end_of_storage = new_start + len;
  }
}

template void vector<beam_effect *, my_allocator<beam_effect *> >::_M_insert_aux(
    beam_effect **, beam_effect *const &);
